function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 500) return 'nums needs 1 to 500 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value of nums is between 1 and 10^5.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is between 1 and the length of nums.';
  return null;
}

