function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 500 : int(1, 8);
  const top = large ? 100000 : 9;
  // Climbing runs make some windows qualify; random restarts add breaks, repeats and drops.
  const climb = large ? 0.9 : 0.6;
  const nums = [];
  for (let i = 0; i < n; i++) {
    if (i > 0 && nums[i - 1] < top && rand() < climb) nums.push(nums[i - 1] + 1);
    else nums.push(int(1, top));
  }
  const k = large && rand() < 0.6 ? int(1, 12) : int(1, n);
  return [nums, k];
}
